/**
 * Voids each selected claim, in list order (people in list order, see PersonRepository#list; a person's claims newest
 * first), exactly as the single void does: judged by ApplyClaimStatus (with the void reason chosen), stored by
 * SaveClaimStatus and written by RecordClaimStatusChanged (its CLAIM_VOIDED, then the figures it moved). Each the single
 * void would refuse, or not on the sheet, is left as it is and counted refused.
 */
public class VoidClaims {
    public void voidAll(@PathVariable("sheetId") String sheetId, @Val BulkVoidRequest request, ClaimRepository claims,
            PersonRepository people, RateRepository rates, PeriodRepository periods, SettingRepository settings,
            RoleRepository roles, SheetRepository sheets, ClaimLog log, VoidReasonRepository voidReasons,
            WatchRepository watches, Rollup rollup, Audit audit, Out<BulkVoidResult> result) {
        String sheet = sheetId.trim();
        Set<Long> selected = new HashSet<>(request.claimIds());
        List<Person> listed = people.list(sheet);
        Map<Long, Integer> personOrder = new HashMap<>();
        for (int i = 0; i < listed.size(); i++) {
            personOrder.put(listed.get(i).id(), i);
        }
        List<Claim> chosen = claims.list(sheet).stream().filter((c) -> selected.contains(c.id()))
                .sorted((a, b) -> Integer.compare(personOrder.getOrDefault(a.personId(), Integer.MAX_VALUE),
                        personOrder.getOrDefault(b.personId(), Integer.MAX_VALUE)))
                .toList();
        ClaimStatusChange change = new ClaimStatusChange(ClaimAction.VOID, ClaimStatus.VOID, request.by(),
                request.reason());
        int voided = 0;
        for (Claim claim : chosen) {
            RollupBefore before = rollup.take(sheet);
            Claim[] changed = new Claim[1];
            Claim[] saved = new Claim[1];
            ClaimNumber[] number = new ClaimNumber[1];
            PreviousDue[] previous = new PreviousDue[1];
            try {
                ApplyClaimStatus.applyJudged(claim, claim, change, people, rates, periods, settings, roles, sheets,
                        claims, log, voidReasons, (c) -> changed[0] = c, (n) -> number[0] = n,
                        (p) -> previous[0] = p);
                new SaveClaimStatus().save(changed[0], change, claims, periods, settings, sheets, log, voidReasons,
                        (c) -> saved[0] = c, (n) -> number[0] = n);
            } catch (InvalidClaimStatusException e) {
                continue;
            }
            voided++;
            new RecordClaimStatusChanged().record(saved[0], change, number[0], previous[0], people, watches, before,
                    rollup, audit);
        }
        result.set(new BulkVoidResult(voided, selected.size() - voided));
    }
}
package net.officefloor.hq.app.claim;

import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.stream.Collectors;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.period.PeriodRepository;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.rollup.RollupBefore;
import net.officefloor.hq.app.role.RoleRepository;
import net.officefloor.hq.app.setting.SettingRepository;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.PathVariable;

/**
 * Opens each selected claim that can be opened, in list order (people in list order, see PersonRepository#list; a person's
 * claims newest first): as the single open does, it must be a DRAFT whose due-by is not inside a closed period, nor one with an empty note whose due is above the note threshold
 * (see ApplyClaimStatus#needsNote), nor one that would take its person past its period's cap (see ClaimRules#overCap; those opened
 * before it in the same press count), takes its
 * number (see ClaimNumbering) and records who opened it (or, its due above the review threshold, goes to REVIEW
 * unnumbered, writing CLAIM_REVIEW, and counts as opened; see ApplyClaimStatus#needsReview), adds its OPEN line to its status log (see ClaimLog), then writes CLAIM_OPENED and the figures it moved (see Rollup).
 * Only a steward opens a claim of a person flagged on the sheet's today (see Person#flaggedOn).
 * A user whose role the sheet does not permit to open opens none. Each that cannot, or is not on the sheet, is left as it is and counted refused.
 */
public class OpenClaims {
    public void open(@PathVariable("sheetId") String sheetId, @Val BulkOpenRequest request, ClaimRepository claims,
            PersonRepository people, RateRepository rates, PeriodRepository periods, SettingRepository settings, RoleRepository roles, SheetRepository sheets, Rollup rollup, Audit audit, ClaimLog log,
            Out<BulkOpenResult> result) {
        String sheet = sheetId.trim();
        Set<Long> selected = new HashSet<>(request.claimIds());
        List<Person> listed = people.list(sheet);
        Map<Long, Integer> personOrder = new HashMap<>();
        for (int i = 0; i < listed.size(); i++) {
            personOrder.put(listed.get(i).id(), i);
        }
        Map<Long, Person> byId = listed.stream().collect(Collectors.toMap(Person::id, (p) -> p));
        List<Claim> chosen = claims.list(sheet).stream().filter((c) -> selected.contains(c.id()))
                .sorted((a, b) -> Integer.compare(personOrder.getOrDefault(a.personId(), Integer.MAX_VALUE),
                        personOrder.getOrDefault(b.personId(), Integer.MAX_VALUE)))
                .toList();
        LateCharge late = LateCharge.of(sheet, sheets, settings, claims);
        int opened = 0;
        String role = roles.roleOf(sheet, request.by());
        boolean steward = RoleRepository.STEWARD.equals(role);
        java.time.LocalDate today = sheets.today(sheet);
        if (!settings.permits(sheet, "open", role)) {
            chosen = List.of();
        }
        for (Claim claim : chosen) {
            if (claim.status() != ClaimStatus.DRAFT || periods.closedOn(sheet, claim.dueBy())
                    || ApplyClaimStatus.needsNote(claim, people, rates, settings, late)
                    || ClaimRules.overCap(claim, periods, claims)
                    || (!steward && byId.containsKey(claim.personId()) && byId.get(claim.personId()).flaggedOn(today))) {
                continue;
            }
            RollupBefore before = rollup.take(sheet);
            boolean review = ApplyClaimStatus.needsReview(claim, people, rates, settings, late);
            String number = review ? null : ClaimNumbering.next(claim, claims, periods, settings, sheets);
            Claim toSave = new Claim(claim.id(), claim.sheetId(), claim.personId(), claim.amount(), claim.date(),
                    claim.note(), review ? ClaimStatus.REVIEW : ClaimStatus.OPEN, number, claim.due(), request.by(), claim.stated(),
                    claim.statedDue(), claim.corrects(), claim.dueBy(), claim.deferredUntil(), claim.proofs(), claim.splitFrom(), claim.ref(), claim.tags(), claim.held());
            if (!claims.updateStatus(toSave, ClaimStatus.DRAFT)) {
                continue;
            }
            opened++;
            log.write(toSave, request.by());
            Person person = byId.get(claim.personId());
            audit.record((review ? "CLAIM_REVIEW" : "CLAIM_OPENED") + " sheet=" + sheet + " by=" + request.by() + " person="
                    + (person == null ? "" : person.name()) + " amount=" + claim.amount().toPlainString()
                    + " date=" + claim.date() + (review ? "" : " number=" + number));
            rollup.record(sheet, request.by(), before);
        }
        result.set(new BulkOpenResult(opened, selected.size() - opened));
    }
}
package net.officefloor.hq.app.claim;

/** The number a status change's audit line carries: the claim's number (a voided claim keeps it). */
public record ClaimNumber(String value) {
}
# PUT /api/sheets/{sheetId}/claims/{claimId}/status — change a claim's status by an action: open
# (DRAFT to OPEN), settle (OPEN to SETTLED, or to PENDING when a clerk settles a claim whose due is above the sheet's
# clerk limit), approve (PENDING to SETTLED) or reject with a reason (PENDING back to OPEN), both by a steward, or void
# (DRAFT, OPEN or PENDING to VOID, or SETTLED to VOID by a steward within 7 days of its settlement), delete (DRAFT to DELETED, counting nowhere), restore (DELETED back to DRAFT, only on the sheet-today it was
# deleted), or resettle by a steward (SETTLED again, its due fixed anew at today's figure as
# an open claim bound by no statement). An action the claim's status does not allow, a claim whose due-by falls inside a closed period,
# settling or approving by the user who opened the claim, settling or approving a claim with no proofs whose due is above
# the proof threshold in force on its date (checked before the clerk limit), approving, rejecting or re-settling by a clerk, a rejection without a
# reason, or an unknown action, is a 409 and a claim not on the sheet a 404, neither writing anything. Opening gives
# the claim the sheet's next number and records who opened it; a voided claim keeps its number. Responds with the
# claim as stored.
validate:
  class: net.officefloor.hq.app.claim.ValidateClaimStatus
  next: rollup
rollup:
  class: net.officefloor.hq.app.rollup.TakeRollup
  govern: [ transaction ]
  next: load
load:
  class: net.officefloor.hq.app.claim.LoadClaim
  govern: [ transaction ]
  next: apply
apply:
  class: net.officefloor.hq.app.claim.ApplyClaimStatus
  govern: [ transaction ]
  next: save
save:
  class: net.officefloor.hq.app.claim.SaveClaimStatus
  govern: [ transaction ]
  next: audit
audit:
  class: net.officefloor.hq.app.claim.RecordClaimStatusChanged
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.claim.RespondWithClaim
# POST /api/sheets/{sheetId}/people/{personId}/approver — makes the user the person's approver (replacing any): they
# may approve or reject the person's PENDING claims as a steward may (see ApplyClaimStatus). A blank user, one not a
# single word, or a body without by is a 400 and a person not on the sheet a 404, none writing anything. Responds with
# the approver.
validate:
  class: net.officefloor.hq.app.person.ValidateApprover
  next: load
load:
  class: net.officefloor.hq.app.person.LoadPerson
  govern: [ transaction ]
  next: apply
apply:
  class: net.officefloor.hq.app.person.ApplyApprover
  govern: [ transaction ]
  next: audit
